const TabymojiAnimation* Tabymoji_GetById(const char* id) {
    if (!id || id[0] == '\0') return &k_tabymoji_animations[0]; // default sleeping_loop
    for (size_t i = 0; i < sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0]); i++) {
        if (strcmp(id, k_tabymoji_animations[i].id) == 0) {
            return &k_tabymoji_animations[i];
        }
    }
    return nullptr;
}

const TabymojiAnimation* Tabymoji_GetByEmotion(const char* emotion) {
    if (!emotion || emotion[0] == '\0') return nullptr;
    
    // Direct emotion mappings
    if (strcmp(emotion, "happy") == 0 || strcmp(emotion, "joyful") == 0 || strcmp(emotion, "pleased") == 0 || strcmp(emotion, "proud") == 0) {
        return Tabymoji_GetById("thumbs_up");
    }
    if (strcmp(emotion, "yeah") == 0 || strcmp(emotion, "celebrate") == 0 || strcmp(emotion, "success") == 0) {
        return Tabymoji_GetById("yeah");
    }
    if (strcmp(emotion, "love") == 0 || strcmp(emotion, "heart") == 0 || strcmp(emotion, "blush") == 0 || strcmp(emotion, "cute") == 0) {
        return Tabymoji_GetById("love_01");
    }
    if (strcmp(emotion, "sad") == 0 || strcmp(emotion, "crying") == 0 || strcmp(emotion, "grief") == 0) {
        return Tabymoji_GetById("disappointed");
    }
    if (strcmp(emotion, "disappointed") == 0 || strcmp(emotion, "frustrated") == 0) {
        return Tabymoji_GetById("hello_disappointed");
    }
    if (strcmp(emotion, "angry") == 0 || strcmp(emotion, "annoyed") == 0 || strcmp(emotion, "mad") == 0) {
        return Tabymoji_GetById("angry_01_loop");
    }
    if (strcmp(emotion, "surprise") == 0 || strcmp(emotion, "shocked") == 0 || strcmp(emotion, "wow") == 0) {
        return Tabymoji_GetById("wow");
    }
    if (strcmp(emotion, "no") == 0 || strcmp(emotion, "reject") == 0 || strcmp(emotion, "cancel") == 0 || strcmp(emotion, "deny") == 0) {
        return Tabymoji_GetById("no");
    }
    if (strcmp(emotion, "sleepy") == 0 || strcmp(emotion, "sleep") == 0 || strcmp(emotion, "standby") == 0) {
        return Tabymoji_GetById("sleeping_loop");
    }
    if (strcmp(emotion, "thinking") == 0 || strcmp(emotion, "loading") == 0 || strcmp(emotion, "waiting") == 0) {
        return Tabymoji_GetById("circle");
    }
    if (strcmp(emotion, "searching") == 0 || strcmp(emotion, "radar") == 0 || strcmp(emotion, "wifi") == 0) {
        return Tabymoji_GetById("searching_loop");
    }
    if (strcmp(emotion, "working") == 0 || strcmp(emotion, "tool") == 0 || strcmp(emotion, "task") == 0 || strcmp(emotion, "mcp") == 0) {
        return Tabymoji_GetById("working_loop");
    }
    if (strcmp(emotion, "calm") == 0 || strcmp(emotion, "relaxed") == 0) {
        return Tabymoji_GetById("calm_idle_01_to_f137");
    }
    if (strcmp(emotion, "startup") == 0 || strcmp(emotion, "waking_up") == 0 || strcmp(emotion, "boot") == 0) {
        return Tabymoji_GetById("startup");
    }
    if (strcmp(emotion, "listening_in") == 0 || strcmp(emotion, "wake") == 0) {
        return Tabymoji_GetById("listening_in");
    }
    if (strcmp(emotion, "listening") == 0 || strcmp(emotion, "listening_loop") == 0) {
        return Tabymoji_GetById("listening_loop");
    }
    if (strcmp(emotion, "talking") == 0 || strcmp(emotion, "speaking") == 0 || strcmp(emotion, "talking_default_loop") == 0) {
        return Tabymoji_GetById("talking_default_loop");
    }
    if (strcmp(emotion, "neutral") == 0 || strcmp(emotion, "robot_2") == 0 || strcmp(emotion, "idle") == 0) {
        return Tabymoji_GetById("idle_01_loop");
    }
    
    // Try matching ID directly
    const TabymojiAnimation* anim = Tabymoji_GetById(emotion);
    if (anim) return anim;
    return nullptr;
}

const TabymojiAnimation* Tabymoji_GetByStatus(const char* status) {
    if (!status || status[0] == '\0') return Tabymoji_GetById("sleeping_loop");
    if (strstr(status, "待命") || strstr(status, "Standby") || strstr(status, "standby") || strstr(status, "Idle") || strstr(status, "idle")) {
        return Tabymoji_GetById("sleeping_loop");
    }
    if (strstr(status, "聆听") || strstr(status, "Listen") || strstr(status, "listen")) {
        return Tabymoji_GetById("listening_loop");
    }
    if (strstr(status, "说话") || strstr(status, "Speak") || strstr(status, "speak") || strstr(status, "Talking") || strstr(status, "talking")) {
        return Tabymoji_GetById("talking_default_loop");
    }
    if (strstr(status, "连接") || strstr(status, "Connect") || strstr(status, "connect") || strstr(status, "Wait") || strstr(status, "wait") || strstr(status, "Logging") || strstr(status, "Checking")) {
        return Tabymoji_GetById("circle");
    }
    if (strstr(status, "Starting") || strstr(status, "Initializing") || strstr(status, "Version") || strstr(status, "Ver ")) {
        return Tabymoji_GetById("startup");
    }
    if (strstr(status, "Config") || strstr(status, "Scan") || strstr(status, "Wi-Fi") || strstr(status, "wifi") || strstr(status, "4G") || strstr(status, "Modem")) {
        return Tabymoji_GetById("searching_loop");
    }
    if (strstr(status, "Upgrade") || strstr(status, "upgrading") || strstr(status, "OTA") || strstr(status, "Loading")) {
        return Tabymoji_GetById("working_loop");
    }
    return Tabymoji_GetById("sleeping_loop");
}

size_t Tabymoji_GetAnimationCount(void) {
    return sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0]);
}

const TabymojiAnimation* Tabymoji_GetByIndex(size_t index) {
    if (index < sizeof(k_tabymoji_animations) / sizeof(k_tabymoji_animations[0])) {
        return &k_tabymoji_animations[index];
    }
    return nullptr;
}
